node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Update order status to cancelled
db.prepare(\"UPDATE orders SET status = 'cancelled', cancel_reason = 'customer requested cancellation' WHERE order_id = 'ORD-E0E671'\").run();

// Update order items status to cancelled
db.prepare(\"UPDATE order_items SET item_status = 'cancelled' WHERE order_id = 'ORD-E0E671'\").run();

// Verify the updates
const order = db.prepare(\"SELECT order_id, status, cancel_reason, total_paid, payment_method FROM orders WHERE order_id = 'ORD-E0E671'\").get();
